// FUN3D scope demo (simulated model)
var regimes=['subsonic','transonic','supersonic','hypersonic'];
for(var i=0;i<regimes.length;i++){console.log('FUN3D: '+regimes[i]);}
console.log('one solver, all speed regimes');

// Conservation demo (simulated model)
var inflow=10, outflow=10;
console.log('mass in='+inflow+' out='+outflow+' conserved='+(inflow===outflow));
console.log('Navier-Stokes: what goes in comes out');

// Grid sizing demo (simulated model)
var zones=[['wall',0.001],['shock',0.01],['farfield',1.0]];
for(var i=0;i<zones.length;i++){console.log(zones[i][0]+': '+zones[i][1]+'m');}
console.log('adapted grid: fine where it matters');

// RANS demo (simulated model)
var models=['Spalart-Allmaras','SST','k-epsilon'];
for(var i=0;i<models.length;i++){console.log('RANS closure: '+models[i]);}
console.log('modeled turbulence, affordable answers');

// DES demo (simulated model)
var regions=[['attached','RANS'],['separated','LES']];
for(var i=0;i<regions.length;i++){console.log(regions[i][0]+' -> '+regions[i][1]);}
console.log('DES: right model per region');

// Heating estimate demo (simulated model)
var v=11000, rho=1e-4;
var q=1.83e-4*Math.sqrt(rho)*Math.pow(v,3)/1e6;
console.log('stagnation heating ~'+q.toFixed(2)+' MW/m^2');
console.log('hypersonic heating estimated');

// Adjoint gradient demo (simulated model)
var vars_=['camber','thickness','sweep'], grad=[-0.4,0.2,-0.1];
for(var i=0;i<vars_.length;i++){console.log('d(drag)/d('+vars_[i]+')='+grad[i]);}
console.log('adjoint: '+vars_.length+' gradients, one extra solve');

// SLS aero demo (simulated model)
console.log('SLS: Cd predicted 0.42, tunnel 0.41');
console.log('aerodynamics validated');

// Capsule demo (simulated model)
var mach=25;
console.log('M='+mach+' bow shock standoff ~0.1D');
console.log('capsule flow solved');

// X-59 demo (simulated model)
console.log('boom 75 PLdB -> thump 65 PLdB (predicted)');
console.log('CFD-designed quiet');

// MMS demo (simulated model)
var orders=[1.98,2.01,1.99];
for(var i=0;i<orders.length;i++){console.log('grid '+i+': order '+orders[i]);}
console.log('second-order verified');

// Tunnel validation demo (simulated model)
var pred=1.02, data=1.0;
console.log('pred '+pred+' data '+data+' err '+((pred-data)*100).toFixed(1)+'%');
console.log('within bounds: VALIDATED');

// Scaling demo (simulated model)
var cores=[128,512,2048], t0=100;
for(var i=0;i<cores.length;i++){console.log(cores[i]+' cores: '+(t0*128/cores[i]).toFixed(1)+'h');}
console.log('scaled to '+cores[2]+' cores');

// Adaptation demo (simulated model)
var cells=1e6;
console.log('adapted: '+(cells*1.4/1e6).toFixed(1)+'M cells (was '+(cells/1e6)+'M)');
console.log('error-driven refinement');

// FUN3D workflow demo (simulated model)
var w=['geometry','grid','physics','solve','validate','optimize'];
for(var i=0;i<w.length;i++){console.log((i+1)+'. '+w[i]);}
console.log('FUN3D workflow complete');
